    raise NotImplementedError("Implement the label specification.")","new":"def slugify(text):
    # Lowercase the input
    text = text.lower()

    # Check if there are any ASCII letters or digits
    has_ascii = any(c.isalnum() and c.isascii() for c in text)
    if not has_ascii:
        return ""

    # Replace runs of non-alphanumeric characters with hyphens
    result = []
    prev_was_hyphen = False

    for char in text:
        if char.isalnum() and char.isascii():
            if prev_was_hyphen:
                pass  # Skip the hyphen from previous run
            else:
                result.append(char)
            prev_was_hyphen = False
        else:
            if not prev_was_hyphen:
                result.append('-')
            prev_was_hyphen = True

    slug = ''.join(result)

    # Strip leading/trailing hyphens
    slug = slug.strip('-')

    return slug"}

